DO $$ BEGIN BEGIN PERFORM * FROM public.restore_reviewed_sales_samples((SELECT manifest_id FROM archived),'restore with stale state','00000000-0000-4000-8000-000000000012'); RAISE EXCEPTION 'Stale root restore accepted'; EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Archived requirement no longer matches its manifest%' THEN RAISE; END IF; END; END $$;
