DELETE FROM public.activity_log WHERE action='late';
CREATE TEMP TABLE restored AS SELECT * FROM public.restore_reviewed_sales_samples((SELECT manifest_id FROM archived),'restore verified disposable samples','00000000-0000-4000-8000-000000000012');
DO $$ BEGIN IF (SELECT replayed FROM restored) OR (SELECT count(*) FROM public.sales_opportunities WHERE archived_at IS NOT NULL)<>0 OR (SELECT count(*) FROM public.customer_requirements WHERE archived_at IS NOT NULL)<>0 OR (SELECT count(*) FROM public.sales_sample_archive_audit_events)<>2 THEN RAISE EXCEPTION 'Restore did not atomically restore roots and audit'; END IF; END $$;
